// A1 — on-device OCR precision/recall on pixel text (scanned IDs, canvas receipts).
// Ground truth: eval/fixtures/ocr_fixtures.json (generated by scripts/gen_ocr_fixtures.mjs,
// images served from server/demo/img/ocr/ through the running server — same pattern as
// redaction_eval.mjs). "Done when": pixel recall >= 0.9 on 20 images with text PII.
//
//   node eval/ocr_eval.mjs        (server must be running; images already generated)

import { launch, openPage, tabIdFor, preview } from "./e2e_harness.mjs";
import { readFile, writeFile, mkdir } from "node:fs/promises";

const SERVER = process.env.SERVER || "http://localhost:8000";
const fixtures = JSON.parse(await readFile("eval/fixtures/ocr_fixtures.json", "utf8"));

const { browser, ctl } = await launch();
const results = [];
for (const fx of fixtures) {
  const url = `${SERVER}${fx.url}`;
  const page = await openPage(browser, url, { width: 700, height: 450 });
  // give the image time to load before the extension scans the page
  await new Promise((r) => setTimeout(r, 500));
  const tabId = await tabIdFor(ctl, url);
  const r = await preview(ctl, tabId, "balanced").catch((e) => ({ ok: false, error: String(e) }));
  if (!r?.ok) {
    results.push({ url: fx.url, error: r?.error ?? "preview failed" });
    await page.close();
    continue;
  }
  const ocrBoxes = r.boxes.filter((b) => fx.gold.some((g) => g.type === b.type));
  const foundTypes = new Set(ocrBoxes.map((b) => b.type));
  const goldTypes = new Set(fx.gold.map((g) => g.type));
  const missed = [...goldTypes].filter((t) => !foundTypes.has(t));
  results.push({
    url: fx.url,
    kind: fx.kind,
    goldTypes: [...goldTypes],
    foundTypes: [...foundTypes],
    missed,
    boxesPainted: ocrBoxes.length,
    tokens: r.tokens?.map((t) => t.type) ?? [],
    perceptionMs: r.timings?.perceptionTotalMs,
  });
  await page.close();
}
await browser.close();

const valid = results.filter((x) => !x.error);
const totalGold = valid.reduce((a, x) => a + x.goldTypes.length, 0);
const totalMissed = valid.reduce((a, x) => a + x.missed.length, 0);
const recall = totalGold ? +((totalGold - totalMissed) / totalGold).toFixed(3) : null;
const imagesFullyCaught = valid.filter((x) => x.missed.length === 0).length;

const summary = {
  generatedAt: new Date().toISOString(),
  images: fixtures.length,
  errors: results.length - valid.length,
  objectRecall: recall, // fraction of gold PII TYPES found somewhere in the image
  imagesFullyCaught: `${imagesFullyCaught}/${valid.length}`,
  results,
};
await mkdir("eval/results", { recursive: true });
await writeFile("eval/results/ocr.json", JSON.stringify(summary, null, 2));
console.log(`OCR: ${imagesFullyCaught}/${valid.length} images fully caught, type-recall=${recall}, ${summary.errors} error(s).`);
for (const r of results) {
  if (r.error) console.log(`  ERROR ${r.url}: ${r.error}`);
  else console.log(`  ${r.missed.length ? "MISS " : "OK   "} ${r.url} gold=${r.goldTypes.join(",")} found=${r.foundTypes.join(",")}${r.missed.length ? ` missed=${r.missed.join(",")}` : ""}`);
}
if (recall !== null && recall < 0.9) {
  console.error(`\nFAIL: recall ${recall} < 0.9 target.`);
  process.exitCode = 1;
}
